/* Kept separate from daily entry and storage so reports never modify history. */
function analyticsPanel(){
  const a=RitmAnalytics.report(state,month,statsHabit),period=`${dateText(a.from)} — ${dateText(a.to)}`;
  const delta=a.delta===null?'Not enough data to compare yet':a.delta===0?'Same as the previous week':`${a.delta>0?'+':''}${a.delta} percentage points vs. the previous week`;
  const rate=a.total.target?Math.round(a.total.complete/a.total.target*100):null;
  return `<section class="analytics-panel" aria-labelledby="analytics-title"><div class="section-title"><div><h2 id="analytics-title">How your rhythm is changing</h2><p class="muted">Completed weeks up to the selected month. The current week is not scored yet.</p></div></div>
    <div class="analytics-overview"><article class="card analytics-score"><div class="card-label">LAST COMPLETE WEEK</div><strong>${a.current.target?a.current.percent+'%':'—'}</strong><span>${dateText(a.current.from)} — ${dateText(a.current.to)}</span><p class="analytics-delta ${a.delta>0?'positive':''}">${delta}</p><small>${a.current.complete} of ${a.current.target} planned completions</small></article>
    <article class="card analytics-trend"><h3>8 weeks at a glance</h3><div class="trend-chart" role="list" aria-label="Goal completion over eight completed weeks">${a.weeks.map(w=>`<div class="trend-column" role="listitem" aria-label="${dateText(w.from)} — ${dateText(w.to)}: ${w.target?w.percent+' percent, '+w.complete+' of '+w.target:'no plan'}"><b>${w.target?w.percent+'%':'—'}</b><div class="trend-track"><i style="height:${w.target?Math.max(w.percent,2):0}%"></i></div><span>${R.parse(w.from).toLocaleDateString('en-GB',{day:'numeric',month:'numeric'})}</span></div>`).join('')}</div><p class="muted">Daily and weekly goals follow your own schedule.</p></article></div>
    <section class="card analytics-habits"><div class="section-title"><div><h3>Consistency by habit</h3><p class="muted">4 complete weeks · ${period}</p></div><span class="analytics-total">${rate===null?'No plan':rate+'% on average'}</span></div>${a.rows.length?a.rows.map(h=>`<div class="regularity-row"><span class="habit-icon" aria-hidden="true">${esc(h.icon)}</span><div class="regularity-info"><strong>${esc(h.name)}${h.archived?' · archived':''}</strong><small>${h.complete} of ${h.target} planned</small><div class="regularity-track"><i style="width:${h.percent}%"></i></div></div><b>${h.percent}%</b></div>`).join(''):'<div class="empty compact">Results will appear after your first complete week with habits.</div>'}</section>
    ${a.strong||a.weak?`<div class="analytics-insights">${a.strong?`<article class="insight positive"><span>BUILDING CONSISTENCY</span><h3>${esc(a.strong.name)}</h3><p>${a.strong.complete} of ${a.strong.target} completions in four weeks. This pace is working for you.</p></article>`:''}${a.weak?`<article class="insight"><span>ROOM TO SIMPLIFY</span><h3>${esc(a.weak.name)}</h3><p>${a.weak.complete} of ${a.weak.target} completions. Try a smaller goal or more convenient days.</p>${a.weak.archived?'':`<button class="text-button" data-edit="${a.weak.id}">Edit habit</button>`}</article>`:''}</div>`:''}
    <p class="muted analytics-method">Reports use the goals in effect on each day. Rest days and archived periods are excluded. Completions beyond a weekly goal do not raise the score above 100%.</p></section>`;
}
